      if (!hasPaper) { try { var n0 = c.numLayers; paperBase(c); var nP = c.numLayers - n0; if (n0 > 0) for (var z = 0; z < nP; z++) c.layer(1).moveToEnd(); } catch (e1) { log.push("FEHLER " + s.id + " Notfall-Papier: " + e1.toString()); } }
